# exec'd from build.py after tools_pages.py; builds /directory/
import csv
MAIL="tapelog@mail.grokbot.com"
CATS={"journals":"Trading journals","charting":"Charting & trading platforms","screeners":"Screeners, scanners & news","brokers":"Brokers","prop-firms":"Prop firms (funded trader programs)","data-apis":"Market data & APIs","backtesting":"Backtesting","education":"Education","calculators":"Free calculators"}
ENT=[dict(name=r[0],url=r[1],cat=r[2],price=r[3],tags=r[4].split(","),desc=r[5],aff=(r[6].strip() if len(r)>6 else "")) for r in csv.reader(open(f"{OUT}/data/tools.tsv"),delimiter="\t") if r and r[0]!="name"]
for s,h,d in TOOLS: ENT.append(dict(name=html.unescape(h).replace("calculator","Calculator")+" (TapeLog)",url=f"{BASE}/tools/{s}/",aff="",cat="calculators",price="Free",tags=["calculator","in-browser","tapelog"],desc=html.unescape(d).split(":")[0]+"."))
