DCSS="<style>.dir{list-style:none;padding:0}.dir li{border:1px solid #dde3ea;border-radius:8px;padding:10px 14px;margin:8px 0}.tag{display:inline-block;background:#eef3f8;border-radius:10px;padding:0 8px;margin:2px;font-size:.78em}.feat{border:2px dashed #f0b400;border-radius:10px;padding:14px;margin:16px 0;background:#fffbef}#q{font:inherit;padding:10px;width:100%;border:1px solid #c9d3dd;border-radius:8px}.chips a{margin-right:10px}.aff{font-size:.72em;color:#5a6673;border:1px solid #c9d3dd;border-radius:8px;padding:0 6px;text-decoration:none;vertical-align:middle}.disc{font-size:.85em;color:#5a6673;background:#f4f7fa;border-radius:8px;padding:8px 12px}</style>"
def tlink(e,inner):
    if e.get("aff"): return f'<a href="{html.escape(e["aff"])}" rel="sponsored nofollow noopener" target="_blank">{inner}</a> <a class="aff" href="/tapelog/disclosure/" title="We may earn a commission if you sign up through this link">affiliate link</a>'
    return f'<a href="{e["url"]}" rel="nofollow noopener" target="_blank">{inner}</a>'
def li(e): return f'<li data-s="{html.escape((e["name"]+" "+e["desc"]+" "+" ".join(e["tags"])+" "+e["cat"]).lower())}" data-c="{e["cat"]}">{tlink(e,"<b>"+html.escape(e["name"])+"</b>")} <span class="small">· {html.escape(e["price"])}</span><br>{html.escape(e["desc"])}<br>{"".join(f"<span class=tag>{html.escape(t)}</span>" for t in e["tags"])}</li>'
def il(es,nm): return {"@context":"https://schema.org","@type":"ItemList","name":nm,"numberOfItems":len(es),"itemListElement":[{"@type":"ListItem","position":i+1,"name":e["name"],"url":e["url"],"description":e["desc"]} for i,e in enumerate(es)]}
FEAT=f'<div class="feat"><b>Featured</b>. <em>Sponsored spots available.</em> Put your trading tool here. <a href="/tapelog/directory/advertise/">See sponsorship options</a>.</div>'
chips='<p class="chips">'+"".join(f'<a href="/tapelog/directory/{c}/">{n}</a>' for c,n in CATS.items())+'</p>'
FOOT=f'<p><a class="btn alt" href="{SUBMIT}">Submit a tool</a> <a class="btn alt" href="https://thetapelog.beehiiv.com/subscribe">Get the free newsletter</a></p><p class="small">Listings are editorial, neutral and free. Prices/plans change, so check each vendor. Most links are plain links. A few are affiliate links, marked "affiliate link": we may earn a commission at no extra cost to you, and it does not affect which tools are listed or how. See our <a href="/tapelog/disclosure/">affiliate disclosure</a>. TapeLog\'s own products are marked "(TapeLog)" or "this site\'s own". Inclusion is not an endorsement or financial advice.</p>'
ADISC='<p class="disc"><b>Disclosure:</b> some links in this directory are affiliate links, marked "affiliate link". We may earn a commission at no extra cost to you. It doesn\'t affect the listings. <a href="/tapelog/disclosure/">Learn more</a>.</p>'
JS="<script>const q=document.getElementById('q');q.addEventListener('input',()=>{const t=q.value.toLowerCase().trim();let n=0;document.querySelectorAll('.dir li').forEach(l=>{const ok=!t||t.split(/\\s+/).every(w=>l.dataset.s.includes(w));l.style.display=ok?'':'none';if(ok)n++});document.getElementById('n').textContent=n;document.querySelectorAll('.dir').forEach(u=>{const h=u.previousElementSibling;if(h&&h.tagName==='H2')h.style.display=[...u.children].some(l=>l.style.display!=='none')?'':'none'})});</script>"
body=f'{DCSS}<h1>Trading tools directory</h1><p>{len(ENT)} hand-picked tools for active traders: journals, charting, screeners, brokers, prop firms, data APIs, backtesting and education. Every link was checked on {TODAY}.</p>{ADISC}{FEAT}<input id="q" type="search" placeholder="Search tools, e.g. futures, free, python, journal" aria-label="Search tools"><p class="small"><span id="n">{len(ENT)}</span> tools shown</p>{chips}'
for c,n in CATS.items():
    es=[e for e in ENT if e["cat"]==c]; body+=f'<h2 id="{c}"><a href="/tapelog/directory/{c}/">{n}</a> ({len(es)})</h2><ul class="dir">'+"".join(map(li,es))+"</ul>"
DFAQ=[("What is the TapeLog trading tools directory?",f"A free, neutral list of {len(ENT)} trading tools across journals, charting, screeners, brokers, prop firms, market data, backtesting and education."),("How do I add my tool?",f"Email {MAIL} with the name, URL, category and a one-line description. Standard listings are free."),("Are these affiliate links?","Most are plain links. A few are affiliate links and are marked \"affiliate link\". If you sign up through one, TapeLog may earn a commission at no extra cost to you. Commissions never decide which tools are listed or how they are described. Featured slots, when sold, are clearly labeled Sponsored.")]
page("/directory/",f"Trading Tools Directory 2026: {len(ENT)} Journals, Screeners, Brokers & More | TapeLog","Free directory of trading tools: journals, charting platforms, screeners, brokers, prop firms, market data APIs, backtesting and education. Search and filter by tag.",body+FOOT+"<h2>FAQ</h2>"+faq_html(DFAQ)+JS,[il(ENT,"Trading tools directory"),faq_ld(DFAQ)])
for c,n in CATS.items():
    es=[e for e in ENT if e["cat"]==c]
    page(f"/directory/{c}/",f"{n}: {len(es)} Tools Compared (2026) | TapeLog Directory",f"{n} for traders: {', '.join(e['name'] for e in es[:5])} and more, with free/paid notes and tags.",
      f'{DCSS}<p class="small"><a href="/tapelog/directory/">Directory</a> › {n}</p><h1>{n}</h1><p>{len(es)} listings. Neutral one-line summaries and pricing notes; verify current pricing with each vendor.</p>{ADISC}{FEAT}<ul class="dir">'+"".join(map(li,es))+"</ul>"+chips+FOOT,[il(es,n)])
